create extension if not exists pgcrypto;
create table if not exists public.roles(id uuid primary key default gen_random_uuid(), name text unique not null check(name in ('admin','editor','sales')));
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, role_id uuid references public.roles(id), created_at timestamptz not null default now());
insert into public.roles(name) values('admin'),('editor'),('sales') on conflict do nothing;
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles p join roles r on p.role_id=r.id where p.id=auth.uid() and r.name in ('admin','editor','sales')) $$;
create table if not exists public.pages(id uuid primary key default gen_random_uuid(), title text not null, slug text unique not null, status text not null default 'draft' check(status in ('draft','published')), content jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.page_sections(id uuid primary key default gen_random_uuid(), page_id uuid not null references pages(id) on delete cascade, section_type text not null, title text, content jsonb not null default '{}'::jsonb, sort_order int not null default 0, enabled boolean not null default true);
create table if not exists public.services(id uuid primary key default gen_random_uuid(), title text not null, slug text unique not null, short_description text, description text not null default '', benefits jsonb not null default '[]', features jsonb not null default '[]', pricing_info text, image_url text, seo_title text, meta_description text, published boolean not null default false, created_at timestamptz not null default now());
create table if not exists public.projects(id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, location text, project_type text, capacity_kw numeric(10,2), description text not null default '', installation_date date, featured boolean not null default false, published boolean not null default false, created_at timestamptz not null default now());
create table if not exists public.project_images(id uuid primary key default gen_random_uuid(), project_id uuid not null references projects(id) on delete cascade, image_url text not null, alt_text text, sort_order int not null default 0);
create table if not exists public.blog_categories(id uuid primary key default gen_random_uuid(), name text unique not null, slug text unique not null);
create table if not exists public.blogs(id uuid primary key default gen_random_uuid(), title text not null, slug text unique not null, excerpt text, content text not null default '', author text, category text, featured_image text, status text not null default 'draft' check(status in ('draft','published')), published_at timestamptz, seo_title text, meta_description text, social_image text, created_at timestamptz not null default now());
create table if not exists public.blog_tags(id uuid primary key default gen_random_uuid(), name text unique not null, slug text unique not null);
create table if not exists public.blog_post_tags(blog_id uuid references blogs(id) on delete cascade, tag_id uuid references blog_tags(id) on delete cascade, primary key(blog_id,tag_id));
create table if not exists public.testimonials(id uuid primary key default gen_random_uuid(), customer_name text not null, review text not null, rating int check(rating between 1 and 5), location text, image_url text, published boolean not null default false);
create table if not exists public.faqs(id uuid primary key default gen_random_uuid(), question text not null, answer text not null, category text, sort_order int not null default 0, published boolean not null default false);
create table if not exists public.leads(id uuid primary key default gen_random_uuid(), name text not null, phone text not null, email text, city text, state text, customer_type text, monthly_bill numeric, interested_capacity text, message text, source text, utm_source text, utm_campaign text, status text not null default 'New' check(status in ('New','Contacted','Qualified','Site Survey Scheduled','Quotation Sent','Negotiation','Won','Lost')), sales_rep uuid references profiles(id), internal_notes text, created_at timestamptz not null default now());
create table if not exists public.lead_activities(id uuid primary key default gen_random_uuid(), lead_id uuid not null references leads(id) on delete cascade, actor uuid references profiles(id), activity text not null, created_at timestamptz not null default now());
create table if not exists public.navigation_items(id uuid primary key default gen_random_uuid(), label text not null, href text not null, parent_id uuid references navigation_items(id) on delete cascade, sort_order int not null default 0, enabled boolean not null default true);
create table if not exists public.website_settings(key text primary key, value jsonb not null, updated_at timestamptz not null default now());
create table if not exists public.seo_metadata(id uuid primary key default gen_random_uuid(), path text unique not null, title text, description text, canonical_url text, og_image text, noindex boolean not null default false, schema jsonb);
create table if not exists public.media_library(id uuid primary key default gen_random_uuid(), bucket text not null, path text not null, alt_text text, uploaded_by uuid references profiles(id), created_at timestamptz not null default now(), unique(bucket,path));
-- Publish original service and educational starter content. These are service descriptions, not claims about completed installations.
insert into public.services(title,slug,short_description,description,benefits,features,image_url,seo_title,meta_description,published) values
('Residential Solar','residential-solar','A rooftop system planned around your home, electricity use and available roof area.','Residential solar begins with your monthly usage, roof condition and goals. EXDELLS helps homeowners understand system sizing, equipment choices, utility coordination and the steps from survey to commissioning. Every recommendation is subject to technical assessment and local requirements.','["Usage-led system sizing","Roof and shade assessment","Installation and commissioning coordination","After-sales support conversation"]','["On-grid systems","Hybrid systems where appropriate","PM Surya Ghar process guidance for eligible customers"]','photo-1509391366360-2e959784a276','Residential Solar in Rajasthan | EXDELLS','Explore rooftop solar planning and installation for Rajasthan homes. Site assessment required.','true'),
('Commercial Solar EPC','commercial-solar','Solar EPC for offices, retail properties and commercial facilities.','Commercial solar planning considers operating hours, daytime loads, available roof or site area, electrical infrastructure and project constraints. EXDELLS coordinates feasibility, engineering, scope, installation planning and commissioning so your team can make decisions with the important assumptions in view.','["Consumption-led feasibility","Clear scope and exclusions","Project coordination","Commissioning and handover"]','["Commercial rooftop systems","Load and tariff review","Phased project planning"]','photo-1497366754035-f200968a6e72','Commercial Solar EPC in Rajasthan | EXDELLS','Commercial solar EPC planning and delivery for Rajasthan businesses.','true'),
('Industrial Solar EPC','industrial-solar','Engineering-led solar planning for industrial operations and complex sites.','Industrial solar requires attention to load profile, operating schedule, roof or ground conditions, structural suitability, electrical integration and site safety. We begin with technical discovery and coordinate a project scope around operational requirements. System feasibility and returns depend on detailed site and tariff assessment.','["Technical site assessment","Load and operating profile review","Engineering and installation coordination","Commissioning documentation"]','["Industrial rooftop feasibility","Electrical integration planning","Project delivery coordination"]','photo-1486406146926-c627a92ad1ab','Industrial Solar EPC Rajasthan | EXDELLS','Industrial solar EPC feasibility and engineering for Rajasthan facilities.','true'),
('On-grid Solar Systems','on-grid-solar','Generate solar electricity in coordination with your grid connection.','An on-grid system works alongside the utility connection and is designed around your site, consumption and applicable interconnection requirements. Grid-connected systems normally shut down during a grid outage unless specifically designed with approved backup equipment. Final design depends on local rules and a technical survey.','["Grid-connected system design","Consumption-based sizing","Utility coordination planning"]','["Rooftop assessment","Inverter and module selection","Interconnection requirements review"]','photo-1509391366360-2e959784a276','On-grid Solar Systems in Rajasthan | EXDELLS','Understand grid-connected rooftop solar systems and site requirements.','true'),
('Hybrid Solar Systems','hybrid-solar','Solar generation with battery storage considered for priority loads.','Hybrid solar combines solar generation, a grid connection and battery storage. The right configuration depends on which loads need backup, how long they must run and the practical battery location. We help assess those requirements before recommending a system.','["Priority-load assessment","Battery capacity planning","Solar and storage integration"]','["Backup load mapping","Battery-ready design options","Commissioning and handover"]','photo-1473341304170-971dccb5ac1e','Hybrid Solar Systems in Rajasthan | EXDELLS','Explore hybrid solar and battery planning for selected backup loads.','true'),
('Off-grid Solar Systems','off-grid-solar','A site-specific solar and storage plan for locations without reliable grid access.','Off-grid design begins with a detailed load inventory and the required autonomy. Seasonal generation, battery chemistry, backup generation, operating practices and maintenance all affect system sizing. A detailed site and load review is essential before equipment selection.','["Load inventory and prioritisation","Autonomy and storage planning","Seasonal generation assessment"]','["Solar array sizing","Battery and inverter integration","Operating and maintenance handover"]','photo-1508514177221-188b1cf16e9d','Off-grid Solar Systems Rajasthan | EXDELLS','Site-specific off-grid solar and storage planning for Rajasthan.','true'),
('PM Surya Ghar Assistance','pm-surya-ghar','Understand the rooftop solar process and prepare for an eligibility conversation.','EXDELLS can help homeowners understand the steps involved in rooftop solar planning and the information commonly needed to discuss programme eligibility. Subsidy eligibility, approved-vendor requirements, amounts and timelines are determined by the current government programme and must be confirmed through official channels.','["Initial eligibility conversation","Application process orientation","System assessment and installation planning"]','["Document checklist discussion","Rooftop suitability review","Guidance on questions to verify officially"]','photo-1497435334941-8c899ee9e8e9','PM Surya Ghar Assistance Rajasthan | EXDELLS','Guidance for Rajasthan homeowners exploring rooftop solar under PM Surya Ghar.','true')
on conflict(slug) do nothing;
insert into public.faqs(question,answer,category,sort_order,published) values
('How do I estimate the right solar capacity for my property?','Start with recent electricity bills, your connection details and usable roof area. A site visit then checks shading, orientation, structure, electrical conditions and local requirements before a final size is recommended.','Planning',1,true),
('Will rooftop solar keep my home powered during a grid outage?','A standard grid-connected inverter usually switches off during an outage for safety. Backup during outages requires a suitable hybrid or backup design, battery capacity and correctly separated priority loads.','System types',2,true),
('What should I prepare before a solar site assessment?','Keep a recent electricity bill available and note your connection type, operating hours, any planned expansion and which loads matter during an outage. Roof access details are also helpful.','Planning',3,true),
('Can EXDELLS help me understand PM Surya Ghar?','We can explain the project planning steps and help you prepare questions about the application process. Eligibility, approved vendors, subsidy values and timelines must be verified against current official programme information.','Subsidy',4,true),
('How long does a solar installation take?','The installation schedule depends on system size, site readiness, equipment availability, utility coordination and approvals. A project-specific timeline is shared after the assessment and scope review.','Installation',5,true),
('What is the difference between on-grid, hybrid and off-grid solar?','On-grid systems work with the utility supply; hybrid systems add storage for selected loads; off-grid systems are designed to operate without a dependable grid connection. Each requires different sizing and operating assumptions.','System types',6,true),
('Can solar be installed on every roof?','Not necessarily. Structural condition, roof material, shading, orientation, waterproofing, access and electrical suitability all matter. A site assessment determines whether the proposed location is suitable.','Planning',7,true),
('How should I compare two solar proposals?','Compare the system capacity and expected production assumptions, module and inverter specifications, mounting design, included electrical work, exclusions, approvals, warranties, commissioning checks and support scope—not only the headline price.','Buying guide',8,true)
on conflict do nothing;
insert into public.blog_categories(name,slug) values ('Project Planning','project-planning'),('System Guides','system-guides'),('Buyer Guides','buyer-guides') on conflict(slug) do nothing;
insert into public.blogs(title,slug,excerpt,content,author,category,status,published_at,seo_title,meta_description) values
('What a rooftop solar site assessment should cover','solar-rooftop-site-assessment','A useful solar assessment checks far more than roof area. Here are the site, electrical and usage details that shape a dependable design.','A good rooftop solar proposal begins with a site assessment. The goal is to understand the conditions that affect safety, generation, system layout and project scope before choosing equipment.\n\n## Start with the electricity use\nRecent bills help establish consumption, tariff structure and the connection type. Ask whether the property has planned load growth, daytime equipment or essential loads that need backup. Monthly bill totals alone are not enough to size a system accurately.\n\n## Check the roof and surroundings\nThe assessment should record usable area, orientation, roof material, condition, access and nearby obstructions. Shadows can move through the day and across seasons, so a quick glance at noon may miss important shading. Structural suitability and waterproofing also need attention before mounting details are finalized.\n\n## Review the electrical connection\nThe main panel, sanctioned load, meter and cable routes influence the system layout. Grid-connected projects also need to account for applicable utility and electrical requirements. The proposal should state what is included in this coordination and what remains subject to approval.\n\n## Ask for the design assumptions\nA clear proposal explains the system capacity, expected production method, equipment specifications, mounting approach, protections, inclusions, exclusions, commissioning checks and support terms. Compare these items side by side instead of comparing only the price per kilowatt.\n\n## Before you decide\nRequest a written scope based on site findings and your current bill. Any savings estimate is conditional on actual generation, self-consumption, export rules, tariffs and system performance. A professional assessment turns a broad estimate into a project-specific conversation.','EXDELLS Editorial','Project Planning','published',now(),'Rooftop Solar Site Assessment Guide | EXDELLS','Learn what a solar site assessment should cover, including roof, shading, electrical and consumption checks.'),
('On-grid, hybrid or off-grid solar: how to compare','on-grid-hybrid-off-grid-solar','The best system architecture depends on grid access and the loads you want to serve. Compare the practical differences before selecting a design.','Solar system labels describe how generation connects to the grid and whether storage is included. Choosing between them starts with your actual power needs—not a product category.\n\n## On-grid: connected to the utility\nAn on-grid system supplies solar electricity while the property remains connected to the grid. It can suit sites that have a reliable connection and want to use solar during generation hours. A standard grid-tied inverter generally shuts down when the grid fails, unless a compliant backup arrangement is part of the design.\n\n## Hybrid: solar with storage\nA hybrid design adds batteries and controls that can serve selected loads during an outage. Battery size should follow a load list and the backup duration you need. Running every appliance through a battery system can make the design larger and more expensive than necessary.\n\n## Off-grid: designed without dependable grid supply\nAn off-grid system must meet loads through solar generation and stored energy, with backup generation considered where appropriate. The design needs to account for seasonal weather, autonomy, critical loads and battery management. Oversizing or undersizing each part can affect reliability.\n\n## Make the choice with a load map\nList the equipment you use, its power rating, hours of use and whether it is essential during an outage. Then compare grid availability, tariff, roof or site conditions, storage requirements and lifecycle costs. A technical assessment can identify the trade-offs and the approvals that apply at your location.','EXDELLS Editorial','System Guides','published',now(),'On-grid vs Hybrid vs Off-grid Solar | EXDELLS','Compare on-grid, hybrid and off-grid solar systems by grid connection, storage and backup needs.'),
('How to read a solar EPC proposal','solar-proposal-checklist','Use this checklist to compare engineering scope, equipment, assumptions, exclusions and handover terms in a solar proposal.','A solar EPC proposal is both a technical plan and a commercial commitment. Reading each section carefully helps you understand what the quoted system includes and what still needs confirmation.\n\n## System design and performance assumptions\nCheck the proposed capacity, module layout, inverter rating, expected energy estimate and the method used to calculate it. Ask whether the estimate accounts for orientation, shading, temperature, system losses and seasonal variation. Treat savings as an estimate, not a guarantee, unless a contract clearly says otherwise.\n\n## Equipment and installation scope\nThe proposal should identify module and inverter specifications, mounting structure, cables, protections, monitoring equipment and installation work. Look for details on roof penetrations, waterproofing, electrical integration, civil work and site restoration. If any item is excluded, ask who will arrange it.\n\n## Approvals, payment and schedule\nClarify which party coordinates utility applications, inspection, net-metering or other applicable approvals. Review payment milestones, schedule assumptions, prerequisites and what happens if approvals or site conditions change.\n\n## Commissioning and after-sales\nConfirm the checks performed at handover, documents you will receive, warranty handling, monitoring setup and the process for raising a service request. Compare the written support commitment across proposals.\n\n## Compare like with like\nAsk each provider to quote against the same scope and assumptions. A lower price may reflect a different system configuration, omitted work or a different support commitment. Make unresolved assumptions explicit before signing.','EXDELLS Editorial','Buyer Guides','published',now(),'Solar EPC Proposal Checklist | EXDELLS','A practical checklist for comparing solar EPC proposals, equipment, scope and project assumptions.')
on conflict(slug) do nothing;
create index if not exists leads_created_idx on leads(created_at desc); create index if not exists leads_status_idx on leads(status); create index if not exists projects_published_idx on projects(published,created_at desc); create index if not exists blogs_status_idx on blogs(status,published_at desc);
alter table profiles enable row level security; alter table roles enable row level security; alter table pages enable row level security; alter table page_sections enable row level security; alter table services enable row level security; alter table projects enable row level security; alter table project_images enable row level security; alter table blog_categories enable row level security; alter table blogs enable row level security; alter table blog_tags enable row level security; alter table blog_post_tags enable row level security; alter table testimonials enable row level security; alter table faqs enable row level security; alter table leads enable row level security; alter table lead_activities enable row level security; alter table navigation_items enable row level security; alter table website_settings enable row level security; alter table seo_metadata enable row level security; alter table media_library enable row level security;
create policy "public published services" on services for select using(published); create policy "staff all services" on services for all using(is_staff()) with check(is_staff());
create policy "public published projects" on projects for select using(published); create policy "staff all projects" on projects for all using(is_staff()) with check(is_staff());
create policy "public project images" on project_images for select using(exists(select 1 from projects p where p.id=project_id and p.published)); create policy "staff project images" on project_images for all using(is_staff()) with check(is_staff());
create policy "public published blogs" on blogs for select using(status='published'); create policy "staff all blogs" on blogs for all using(is_staff()) with check(is_staff());
create policy "public published faqs" on faqs for select using(published); create policy "staff all faqs" on faqs for all using(is_staff()) with check(is_staff());
create policy "public published testimonials" on testimonials for select using(published); create policy "staff all testimonials" on testimonials for all using(is_staff()) with check(is_staff());
create policy "public pages" on pages for select using(status='published'); create policy "staff pages" on pages for all using(is_staff()) with check(is_staff());
create policy "staff page sections" on page_sections for all using(is_staff()) with check(is_staff());
create policy "staff leads" on leads for select using(is_staff()); create policy "staff update leads" on leads for update using(is_staff()) with check(is_staff());
create policy "staff activities" on lead_activities for all using(is_staff()) with check(is_staff());
create policy "public nav" on navigation_items for select using(enabled); create policy "staff nav" on navigation_items for all using(is_staff()) with check(is_staff());
create policy "public settings" on website_settings for select using(key not in ('private','secrets')); create policy "staff settings" on website_settings for all using(is_staff()) with check(is_staff());
create policy "public seo" on seo_metadata for select using(not noindex); create policy "staff seo" on seo_metadata for all using(is_staff()) with check(is_staff());
create policy "public blog categories" on blog_categories for select using(true); create policy "staff blog categories" on blog_categories for all using(is_staff()) with check(is_staff());
create policy "public blog tags" on blog_tags for select using(true); create policy "staff blog tags" on blog_tags for all using(is_staff()) with check(is_staff());
create policy "public blog post tags" on blog_post_tags for select using(true); create policy "staff blog post tags" on blog_post_tags for all using(is_staff()) with check(is_staff());
create policy "own profile" on profiles for select using(id=auth.uid() or is_staff()); create policy "staff profiles" on profiles for all using(is_staff()) with check(is_staff());
create policy "read roles" on roles for select using(is_staff()); create policy "staff media" on media_library for all using(is_staff()) with check(is_staff());
insert into storage.buckets(id,name,public) values ('logos','logos',true),('website-images','website-images',true),('project-images','project-images',true),('blog-images','blog-images',true),('testimonials','testimonials',true) on conflict(id) do nothing;
create policy "public read site media" on storage.objects for select using(bucket_id in ('logos','website-images','project-images','blog-images','testimonials'));
create policy "staff upload media" on storage.objects for insert with check(bucket_id in ('logos','website-images','project-images','blog-images','testimonials') and public.is_staff());
create policy "staff update media" on storage.objects for update using(public.is_staff()) with check(public.is_staff()); create policy "staff delete media" on storage.objects for delete using(public.is_staff());
